namespace Countify.Application.Features.Banks;

public class BankAccountDto
{
    public Guid Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = "";
    public string AccountNumber { get; set; } = ""; public Guid AccountingAccountId { get; set; } public string? AccountingAccountCode { get; set; }
    public string? AccountingAccountName { get; set; } public Guid CurrencyId { get; set; } public string? CurrencyCode { get; set; } public string? CurrencyName { get; set; } public int? CutoffDay { get; set; }
    public string? CheckNumber { get; set; } public decimal Interest { get; set; } public decimal Balance { get; set; }
    public Guid? DepartmentId { get; set; } public Guid? ProjectId { get; set; } public bool IsInactive { get; set; } public string? DefaultNdNcText { get; set; }
}
public class BankTransactionTypeDto { public Guid Id { get; set; } public string Code { get; set; } = ""; public string MovementType { get; set; } = ""; public string TransactionType { get; set; } = ""; }
public class BankTransactionDto
{
    public Guid Id { get; set; } public Guid BankAccountId { get; set; } public string? BankAccountName { get; set; } public Guid TransactionTypeId { get; set; }
    public string? TransactionTypeCode { get; set; } public string TransactionTypeValue { get; set; } = ""; public DateTime Date { get; set; }
    public Guid CurrencyId { get; set; } public string? CurrencyCode { get; set; } public decimal ExchangeRate { get; set; } public decimal Amount { get; set; } public decimal LocalAmount { get; set; }
    public string? Reference { get; set; } public string? Beneficiary { get; set; } public string? Concept { get; set; } public Guid? DepartmentId { get; set; }
    public Guid? ProjectId { get; set; } public bool Reconciled { get; set; } public bool Voided { get; set; } public Guid? JournalEntryId { get; set; }
    public Guid CounterpartAccountId { get; set; } public Guid? BankReconciliationId { get; set; }
}
public class BankReconciliationDto
{
    public Guid Id { get; set; } public Guid BankAccountId { get; set; } public string? BankAccountName { get; set; }
    public DateTime ReconciliationDate { get; set; } public decimal StatementBalance { get; set; } public decimal BookBalance { get; set; }
    public bool IsClosed { get; set; } public string? Notes { get; set; } public int TransactionCount { get; set; }
}
public class BankStatementDto
{
    public Guid BankAccountId { get; set; } public string BankAccountName { get; set; } = ""; public DateTime FromDate { get; set; } public DateTime ToDate { get; set; }
    public decimal OpeningBalance { get; set; } public decimal DebitTotal { get; set; } public decimal CreditTotal { get; set; } public decimal ClosingBalance { get; set; }
    public List<BankTransactionDto> Transactions { get; set; } = [];
}
public class BankAccountProfile : Profile
{
    public BankAccountProfile()
    {
        CreateMap<BankAccount, BankAccountDto>().ForMember(d => d.AccountingAccountCode, o => o.MapFrom(s => s.AccountingAccount!.Code)).ForMember(d => d.AccountingAccountName, o => o.MapFrom(s => s.AccountingAccount!.Name)).ForMember(d => d.CurrencyCode, o => o.MapFrom(s => s.Currency!.Code)).ForMember(d => d.CurrencyName, o => o.MapFrom(s => s.Currency!.Name));
        CreateMap<BankTransactionType, BankTransactionTypeDto>();
        CreateMap<BankTransaction, BankTransactionDto>().ForMember(d => d.BankAccountName, o => o.MapFrom(s => s.BankAccount!.Name)).ForMember(d => d.TransactionTypeCode, o => o.MapFrom(s => s.TransactionType!.Code)).ForMember(d => d.CurrencyCode, o => o.MapFrom(s => s.Currency!.Code));
        CreateMap<BankReconciliation, BankReconciliationDto>().ForMember(d => d.BankAccountName, o => o.MapFrom(s => s.BankAccount!.Name)).ForMember(d => d.TransactionCount, o => o.MapFrom(s => s.Transactions.Count));
    }
}

public record CreateBankAccountCommand(string Code, string Name, string AccountNumber, Guid AccountingAccountId, Guid CurrencyId, int? CutoffDay, string? CheckNumber, decimal Interest, decimal Balance, Guid? DepartmentId, Guid? ProjectId, bool IsInactive, string? DefaultNdNcText) : IRequest<Response<Guid>>;
public record UpdateBankAccountCommand(Guid Id, string Code, string Name, string AccountNumber, Guid AccountingAccountId, Guid CurrencyId, int? CutoffDay, string? CheckNumber, decimal Interest, decimal Balance, Guid? DepartmentId, Guid? ProjectId, bool IsInactive, string? DefaultNdNcText) : IRequest<Response<bool>>;
public record DeleteBankAccountCommand(Guid Id) : IRequest<Response<bool>>;
public record GetBankAccountsQuery : IRequest<Response<List<BankAccountDto>>>;
public record CreateBankTransactionTypeCommand(string Code, string MovementType, string TransactionType) : IRequest<Response<Guid>>;
public record UpdateBankTransactionTypeCommand(Guid Id, string Code, string MovementType, string TransactionType) : IRequest<Response<bool>>;
public record DeleteBankTransactionTypeCommand(Guid Id) : IRequest<Response<bool>>;
public record GetBankTransactionTypesQuery : IRequest<Response<List<BankTransactionTypeDto>>>;
 public record CreateBankTransactionCommand(Guid BankAccountId, Guid TransactionTypeId, string TransactionTypeValue, DateTime Date, Guid CurrencyId, decimal ExchangeRate, decimal Amount, decimal LocalAmount, string? Reference, string? Beneficiary, string? Concept, Guid? DepartmentId, Guid? ProjectId, bool Reconciled, bool Voided, Guid? JournalEntryId, Guid CounterpartAccountId) : IRequest<Response<Guid>>;
 public record UpdateBankTransactionCommand(Guid Id, Guid BankAccountId, Guid TransactionTypeId, string TransactionTypeValue, DateTime Date, Guid CurrencyId, decimal ExchangeRate, decimal Amount, decimal LocalAmount, string? Reference, string? Beneficiary, string? Concept, Guid? DepartmentId, Guid? ProjectId, bool Reconciled, bool Voided, Guid? JournalEntryId, Guid CounterpartAccountId) : IRequest<Response<bool>>;
 public record VoidBankTransactionCommand(Guid Id) : IRequest<Response<bool>>;
public record DeleteBankTransactionCommand(Guid Id) : IRequest<Response<bool>>;
 public record GetBankTransactionsQuery(Guid? BankAccountId = null) : IRequest<Response<List<BankTransactionDto>>>;
